CREATE FUNCTION pg_temp.check_result_case(label TEXT, data TEXT, provenance TEXT, expected BOOLEAN)
RETURNS BOOLEAN LANGUAGE PLPGSQL AS $$
DECLARE accepted BOOLEAN:=TRUE; result JSONB;
BEGIN
 BEGIN result:=internal.parse_initial_result_data_v1(data,provenance);
 EXCEPTION WHEN SQLSTATE '22023' OR invalid_text_representation OR numeric_value_out_of_range THEN accepted:=FALSE;
 END;
 IF accepted IS DISTINCT FROM expected THEN RETURN FALSE; END IF;
 IF accepted AND result IS DISTINCT FROM data::JSONB THEN RETURN FALSE; END IF;
 RETURN TRUE;
END; $$;
