CREATE TEMP TABLE result_evidence_fixture(v JSONB);
INSERT INTO result_evidence_fixture VALUES ($evidence${"reference":{"owner_id":"00000000-0000-4000-8000-000000000101","scan_id":"00000000-0000-4000-8000-000000000101","invocation_id":"00000000-0000-4000-8000-000000000101","result_evidence_id":"00000000-0000-4000-8000-000000000102","submission_digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","config_digest":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","funding_binding_digest":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"},"result_canonical":"{\"config_digest\":\"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\",\"data\":{\"ai_reasoning\":\"Synthetic identification fixture.\",\"blur_score\":\"0.2\",\"candidates\":[{\"confidence_score\":\"0.2\",\"distinguishing_feature\":\"synthetic difference\",\"scientific_name\":\"Danaus gilippus\"}],\"colors\":[],\"common_name\":\"Monarch Butterfly\",\"confidence_score\":\"0.87\",\"estimated_size_cm\":\"8.5\",\"extracted_visual_traits\":[\"synthetic wings\"],\"identification_provenance\":{\"binding\":\"openai_photo_v1\",\"confidence\":\"openai_unqualified_v1\",\"diagnostic_trigger\":null,\"generation\":{\"image_detail\":\"high\",\"max_output_tokens\":8192,\"reasoning_effort\":\"low\"},\"model\":\"gpt-6-sol\",\"operation\":\"scan_identification\",\"policy_version\":1,\"prompt\":\"openai_identify_vision_confidence_v1\",\"prompt_diagnostic_trigger\":null,\"provider\":\"openai\",\"safety\":\"openai_photo_moderation_v1\",\"schema\":\"merian_openai_identify_v1\",\"timeout_ms\":90000,\"variant\":\"multimodal\",\"version\":2},\"image_quality\":{\"diagnostic_utility\":9,\"framing\":7,\"overall_score\":82,\"sharpness\":8},\"inference_tier\":\"flash\",\"insight_data\":{\"ai_reasoning\":\"Synthetic identification fixture.\",\"hazard_type\":\"none\"},\"is_biological_subject\":true,\"is_live_capture\":true,\"pet_identification\":null,\"scan_id\":\"00000000-0000-4000-8000-000000000101\",\"scientific_name\":\"Danaus plexippus\"},\"funding_binding_digest\":\"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc\",\"invocation_id\":\"00000000-0000-4000-8000-000000000101\",\"provider_usage\":{\"cache_write_tokens\":null,\"cached_tokens\":null,\"candidate_tokens\":null,\"input_tokens\":null,\"modality_breakdown\":{},\"output_tokens\":null,\"service_tier\":null,\"thinking_tokens\":null,\"tool_tokens\":null,\"total_tokens\":null},\"scan_id\":\"00000000-0000-4000-8000-000000000101\",\"state\":\"validated_success\",\"submission_digest\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\"version\":1}","provenance_canonical":"{\"binding\":\"openai_photo_v1\",\"confidence\":\"openai_unqualified_v1\",\"diagnostic_trigger\":null,\"generation\":{\"image_detail\":\"high\",\"max_output_tokens\":8192,\"reasoning_effort\":\"low\"},\"model\":\"gpt-6-sol\",\"operation\":\"scan_identification\",\"policy_version\":1,\"prompt\":\"openai_identify_vision_confidence_v1\",\"prompt_diagnostic_trigger\":null,\"provider\":\"openai\",\"safety\":\"openai_photo_moderation_v1\",\"schema\":\"merian_openai_identify_v1\",\"timeout_ms\":90000,\"variant\":\"multimodal\",\"version\":2}","result_digest":"d01b36572dac7c19ec45fc8e3b600bcbb274389991d0dbcf97d5b23b87cbad9a","provenance_digest":"cf88ae85073248a1a0b0bc16f911cb327b12f54c267bebb32200b0538e820727"}$evidence$::JSONB);
CREATE FUNCTION pg_temp.primary_result_v1(resolution TEXT) RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE d JSONB; identity JSONB; names_null BOOLEAN:=resolution IN ('unresolved_biological','non_biological');
BEGIN
 SELECT (v->>'result_canonical')::JSONB->'data' INTO d FROM result_evidence_fixture;
 identity:=jsonb_build_object('version',1,'resolution',resolution,'scientific_name',CASE WHEN names_null THEN 'null'::JSONB ELSE d->'scientific_name' END,'common_name',CASE WHEN names_null THEN 'null'::JSONB ELSE d->'common_name' END);
 d:=jsonb_set(d,'{identification_provenance,schema}','"merian_identify_primary_v1"')||jsonb_build_object(
 'primary_identification',identity,'scientific_name',identity->'scientific_name','common_name',identity->'common_name',
 'is_biological_subject',resolution<>'non_biological','is_new_to_merian_dictionary',FALSE,'pet_identification','null'::JSONB,
 'candidates',CASE WHEN resolution='species' THEN (SELECT jsonb_agg(c||'{"taxon_rank":"species"}'::JSONB) FROM jsonb_array_elements(d->'candidates') c) ELSE 'null'::JSONB END);
 RETURN d;
END $$;
CREATE FUNCTION pg_temp.semantic_accepts_v1(d JSONB) RETURNS BOOLEAN LANGUAGE plpgsql AS $$
BEGIN
 PERFORM internal.parse_initial_result_data_v1(internal.initial_canonical(d),internal.initial_canonical(d->'identification_provenance'));
 RETURN TRUE;
EXCEPTION WHEN SQLSTATE '22023' THEN RETURN FALSE;
END $$;
SELECT extensions.ok(pg_temp.semantic_accepts_v1(pg_temp.primary_result_v1(r)),'primary accepted: '||r)
 FROM unnest(ARRAY['species','genus','family','unresolved_biological','non_biological']) r;
SELECT extensions.ok(NOT pg_temp.semantic_accepts_v1(d),label) FROM (VALUES
 ('missing primary',pg_temp.primary_result_v1('species')-'primary_identification'),
 ('legacy with primary',jsonb_set(pg_temp.primary_result_v1('species'),'{identification_provenance,schema}','"merian_identify_v1"')),
 ('subject contradicts',pg_temp.primary_result_v1('species')||'{"is_biological_subject":false}'::JSONB),
 ('top identity contradicts',pg_temp.primary_result_v1('species')||'{"common_name":"Other"}'::JSONB),
 ('species missing scientific',jsonb_set(pg_temp.primary_result_v1('species'),'{primary_identification,scientific_name}','null')),
 ('unresolved scientific name',jsonb_set(pg_temp.primary_result_v1('unresolved_biological'),'{primary_identification,scientific_name}','"Unexpected"')),
 ('leading whitespace',jsonb_set(pg_temp.primary_result_v1('species'),'{primary_identification,scientific_name}','" Danaus plexippus"')),
 ('unicode trim whitespace',jsonb_set(pg_temp.primary_result_v1('species'),'{primary_identification,common_name}',to_jsonb(U&'\FEFFMonarch Butterfly'::TEXT))),
 ('control name',jsonb_set(pg_temp.primary_result_v1('species'),'{primary_identification,common_name}',to_jsonb('Monarch'||chr(127)))),
 ('species rank missing',jsonb_set(pg_temp.primary_result_v1('species'),'{candidates,0}',(pg_temp.primary_result_v1('species')#>'{candidates,0}')-'taxon_rank')),
 ('too many alternatives',jsonb_set(pg_temp.primary_result_v1('species'),'{candidates}',(pg_temp.primary_result_v1('species')->'candidates')||(pg_temp.primary_result_v1('species')->'candidates')||(pg_temp.primary_result_v1('species')->'candidates'))),
 ('non species alternatives',jsonb_set(pg_temp.primary_result_v1('genus'),'{candidates}',pg_temp.primary_result_v1('species')->'candidates')),
 ('non species dictionary',pg_temp.primary_result_v1('genus')||'{"is_new_to_merian_dictionary":true}'::JSONB),
 ('non species enrichment',pg_temp.primary_result_v1('genus')||'{"wikipedia_url":"https://example.com"}'::JSONB),
 ('family genus',pg_temp.primary_result_v1('family')||'{"taxonomy":{"genus":"Danaus"}}'::JSONB)
) cases(label,d);
SELECT extensions.ok(NOT pg_temp.semantic_accepts_v1(jsonb_set((v->>'result_canonical')::JSONB->'data','{candidates,0,taxon_rank}','"species"')),'legacy cannot carry ranked candidates') FROM result_evidence_fixture;

CREATE FUNCTION pg_temp.result_usage_v1() RETURNS JSONB LANGUAGE SQL AS $$
 SELECT (v->>'result_canonical')::JSONB->'provider_usage' FROM result_evidence_fixture;
$$;
SELECT extensions.ok(internal.initial_result_usage_matches_v1(pg_temp.result_usage_v1(),'openai'),'original bounded usage accepted');
SELECT extensions.ok(internal.initial_result_usage_matches_v1(pg_temp.result_usage_v1()||'{"modality_breakdown":{"prompt":{"image":1},"cached":{},"candidates":{"text":2},"tool":{}}}','gemini'),'gemini bounded modalities accepted');
SELECT extensions.ok(NOT internal.initial_result_usage_matches_v1(u,'openai'),label) FROM (VALUES
 ('extra usage',pg_temp.result_usage_v1()||'{"extra":1}'),
 ('missing usage',pg_temp.result_usage_v1()-'input_tokens'),
 ('counter string',pg_temp.result_usage_v1()||'{"input_tokens":"1"}'),
 ('counter negative',pg_temp.result_usage_v1()||'{"input_tokens":-1}'),
 ('counter excessive',pg_temp.result_usage_v1()||'{"input_tokens":100000001}'),
 ('tier unknown',pg_temp.result_usage_v1()||'{"service_tier":"other"}'),
 ('openai modality extra',pg_temp.result_usage_v1()||'{"modality_breakdown":{"prompt":{}}}')
) cases(label,u);
SELECT extensions.ok(NOT internal.initial_result_usage_matches_v1(pg_temp.result_usage_v1(),'gemini'),'gemini requires all four categories');
SELECT extensions.ok(NOT internal.initial_result_usage_matches_v1(pg_temp.result_usage_v1(),'other'),'unknown usage provider denied');
SELECT extensions.ok(NOT internal.initial_result_usage_matches_v1(pg_temp.result_usage_v1()||'{"modality_breakdown":{"prompt":{"unknown":1},"cached":{},"candidates":{},"tool":{}}}','gemini'),'gemini unknown modality denied');

SELECT extensions.is(internal.parse_initial_result_evidence_v1(v->>'result_canonical',v->>'provenance_canonical',v->>'result_digest',v->>'provenance_digest'),(v->>'result_canonical')::JSONB,'original Deno wrapper and actual-LF hashes match') FROM result_evidence_fixture;
CREATE FUNCTION pg_temp.wrapper_accepts_v1(patch JSONB,bad_hash BOOLEAN DEFAULT FALSE,bad_provenance_hash BOOLEAN DEFAULT FALSE)
RETURNS BOOLEAN LANGUAGE plpgsql AS $$
DECLARE e JSONB; result JSONB; text_value TEXT; result_hash TEXT; provenance_hash TEXT;
BEGIN
 SELECT v INTO e FROM result_evidence_fixture;
 result:=(e->>'result_canonical')::JSONB||patch;
 text_value:=internal.initial_canonical(result);
 result_hash:=encode(extensions.digest(convert_to('merian.initial-analysis.result.v1'||chr(10)||text_value,'UTF8'),'sha256'),'hex');
 provenance_hash:=e->>'provenance_digest';
 IF bad_hash THEN result_hash:=repeat('f',64); END IF;
 IF bad_provenance_hash THEN provenance_hash:=repeat('f',64); END IF;
 PERFORM internal.parse_initial_result_evidence_v1(text_value,e->>'provenance_canonical',result_hash,provenance_hash);
 RETURN TRUE;
EXCEPTION WHEN SQLSTATE '22023' THEN RETURN FALSE;
END $$;
SELECT extensions.ok(NOT pg_temp.wrapper_accepts_v1(patch),label) FROM (VALUES
 ('wrapper extra','{"extra":true}'::JSONB),('wrapper version','{"version":2}'),('wrapper state','{"state":"draft"}'),
 ('scan mismatch','{"scan_id":"00000000-0000-4000-8000-000000000102"}'),('invalid invocation','{"invocation_id":"invalid"}'),
 ('null identity','{"invocation_id":null}'),('invalid binding digest','{"funding_binding_digest":"invalid"}'),
 ('wrapper usage','{"provider_usage":{}}')
) cases(label,patch);
SELECT extensions.ok(NOT pg_temp.wrapper_accepts_v1('{}',TRUE),'wrong result hash denied');
SELECT extensions.ok(NOT pg_temp.wrapper_accepts_v1('{}',FALSE,TRUE),'wrong provenance hash denied');
SELECT extensions.ok(NOT has_function_privilege(role_name,signature,'EXECUTE'),role_name||' denied '||signature)
 FROM unnest(ARRAY['anon','authenticated','service_role']) role_name
 CROSS JOIN unnest(ARRAY['internal.initial_result_primary_matches_v1(jsonb)','internal.initial_result_usage_matches_v1(jsonb,text)','internal.parse_initial_result_evidence_v1(text,text,text,text)']) signature;
SELECT extensions.ok(NOT prosecdef,proname||' remains invoker') FROM pg_proc
 WHERE oid IN ('internal.initial_result_primary_matches_v1(jsonb)'::regprocedure,'internal.initial_result_usage_matches_v1(jsonb,text)'::regprocedure,'internal.parse_initial_result_evidence_v1(text,text,text,text)'::regprocedure);
SELECT * FROM extensions.finish();
ROLLBACK;
